(193, 'astra-sites-and-pages-page-4', 'a:15:{s:8:\"id-53724\";a:22:{s:5:\"title\";s:29:\"Food Blogger &amp; Influencer\";s:2:\"id\";i:53724;s:12:\"publish-date\";i:1623427699;s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2021/05/food-blogger-02-home.jpg\";s:19:\"thumbnail-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2021/05/food-blogger-02-home.jpg\";s:28:\"fullpage-thumbnail-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2021/05/food-blogger-02-home.jpg\";s:14:\"astra-site-url\";s:34:\"//websitedemos.net/food-blogger-04\";s:20:\"astra-site-parent-id\";i:2000;s:15:\"astra-sites-tag\";a:9:{i:1652;s:7:\"blogger\";i:1654;s:15:\"content-creator\";i:2173;s:11:\"food-drinks\";i:2171;s:22:\"food-drinks-influencer\";i:2172;s:19:\"food-drinks-vlogger\";i:890;s:12:\"food-blogger\";i:1547;s:10:\"influencer\";i:2163;s:23:\"social-media-influencer\";i:1837;s:7:\"vlogger\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:37;s:4:\"blog\";}s:29:\"astra-sites-template-category\";a:6:{i:2828;s:4:\"blog\";i:2785;s:4:\"food\";i:2770;s:8:\"personal\";i:2776;s:10:\"restaurant\";i:2801;s:5:\"video\";i:2870;s:4:\"vlog\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:2:{i:2497;s:4:\"blog\";i:2926;s:5:\"video\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-footer-elementor.php\";s:4:\"name\";s:35:\"Elementor - Header, Footer & Blocks\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1027:\"<!-- wp:paragraph -->\n<p>Are you a food blogger, an influencer, or both? Want to build a website and become an authority in your niche? We\'ve got you covered with this Food Blogger &amp; Influencer website template.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>It\'s elegant, professional, and clean — perfect for showcasing your content, be it reviews of exotic new dishes or the latest restaurant in the neighborhood. Plus, it\'s got social media integrations so you can easily share and engage with your audience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Food Blogger &amp; Influencer template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Clean, professional, and elegant website template</li><li>Easy to use with social media integrations</li><li>Option to include latest review videos as well</li><li>Build your email list with the newsletter sign-up form integrated on the homepage</li><li>Compatible with leading drag and drop page builders</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:77:\"Perfect website template for food bloggers, influencers or restaurant reviews\";s:5:\"pages\";a:5:{s:8:\"id-53726\";a:12:{s:5:\"title\";s:7:\"Contact\";s:18:\"featured-image-url\";s:79:\"https://websitedemos.net/wp-content/uploads/2021/05/food-blogger-02-contact.jpg\";s:19:\"thumbnail-image-url\";s:79:\"https://websitedemos.net/wp-content/uploads/2021/05/food-blogger-02-contact.jpg\";s:18:\"astra-page-api-url\";s:64:\"https://websitedemos.net/food-blogger-04/wp-json/wp/v2/pages/904\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:43:\"//websitedemos.net/food-blogger-04/contact/\";s:15:\"astra-sites-tag\";a:1:{i:415;s:7:\"contact\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:74;s:4:\"blog\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"w