:1017;s:10:\"e-commerce\";i:496;s:9:\"ecommerce\";i:1817;s:15:\"ecommerce-store\";i:2419;s:9:\"eshopping\";i:2382;s:15:\"jewellery-store\";i:2529;s:13:\"jewelry-store\";i:2383;s:22:\"online-jewellery-store\";i:2422;s:13:\"online-market\";i:732;s:11:\"online-shop\";i:2420;s:15:\"online-shopping\";i:383;s:12:\"online-store\";i:2421;s:9:\"purchases\";i:2417;s:8:\"reseller\";i:733;s:4:\"shop\";i:2416;s:8:\"shopping\";i:966;s:12:\"woo-commerce\";i:1024;s:11:\"woocommerce\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:38;s:9:\"ecommerce\";}s:29:\"astra-sites-template-category\";a:3:{i:2769;s:9:\"ecommerce\";i:2838;s:9:\"jewellery\";i:2857;s:15:\"online-shopping\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:1:{i:2495;s:9:\"ecommerce\";}s:16:\"required-plugins\";a:6:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:27:\"checkout-plugins-stripe-woo\";s:4:\"init\";s:59:\"checkout-plugins-stripe-woo/checkout-plugins-stripe-woo.php\";s:4:\"name\";s:41:\"Checkout Plugins - Stripe for WooCommerce\";}i:2;a:3:{s:4:\"slug\";s:11:\"woocommerce\";s:4:\"init\";s:27:\"woocommerce/woocommerce.php\";s:4:\"name\";s:11:\"WooCommerce\";}i:3;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}i:4;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:5;a:3:{s:4:\"slug\";s:22:\"variation-swatches-woo\";s:4:\"init\";s:49:\"variation-swatches-woo/variation-swatches-woo.php\";s:4:\"name\";s:34:\"Variation Swatches for WooCommerce\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1116:\"<!-- wp:paragraph -->\n<p>Want to sell jewelry to a broader audience? Consider building an online store! Import our easy-to-use Jewellery Store template and launch your store quickly. Accept orders and payments round the clock through your website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The clean and minimalistic design has all the correct elements to help you build a high-converting store. From impressive background effects to displaying products based on categories and latest arrivals, Jewellery Store is the perfect web template for your store.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Jewellery Store template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Clean and simple design that has everything you need to build a fantastic online store</li><li>Display products based on categories, such as earrings, necklaces, rings, and more</li><li>Product page displays various payment options as well as related products</li><li>Straightforward checkout process</li><li>Well integrated with the WordPress eCommerce plugin, WooCommerce</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:79:\"Beautiful website template perfect for building an online store to sell jewelry\";s:5:\"pages\";a:3:{s:8:\"id-58167\";a:12:{s:5:\"title\";s:7:\"Contact\";s:18:\"featured-image-url\";s:82:\"https://websitedemos.net/wp-content/uploads/2021/09/jewellery-store-02-contact.jpg\";s:19:\"thumbnail-image-url\";s:82:\"https://websitedemos.net/wp-content/uploads/2021/09/jewellery-store-02-contact.jpg\";s:18:\"astra-page-api-url\";s:66:\"https://websitedemos.net/jewellery-store-04/wp-json/wp/v2/pages/20\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:46:\"//websitedemos.net/jewellery-store-04/contact/\";s:15:\"astra-sites-tag\";a:1:{i:415;s:7:\"contact\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:64;s:9:\"ecommerce\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:12:\"wp