5;s:17:\"digital-marketing\";i:467;s:9:\"learndash\";i:975;s:15:\"online-learning\";i:720;s:9:\"tutorials\";}s:16:\"astra-sites-type\";s:4:\"free\";s:19:\"astra-site-category\";a:2:{i:27;s:8:\"business\";i:39;s:4:\"free\";}s:29:\"astra-sites-template-category\";a:6:{i:2825;s:8:\"coaching\";i:2835;s:9:\"elearning\";i:2796;s:9:\"marketing\";i:2880;s:10:\"membership\";i:2827;s:13:\"online-course\";i:2873;s:5:\"tutor\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:1:{i:2494;s:9:\"elearning\";}s:16:\"required-plugins\";a:6:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:8:\"sfwd-lms\";s:4:\"init\";s:21:\"sfwd-lms/sfwd_lms.php\";s:4:\"name\";s:13:\"LearnDash LMS\";}i:2;a:3:{s:4:\"slug\";s:21:\"learndash-course-grid\";s:4:\"init\";s:47:\"learndash-course-grid/learndash_course_grid.php\";s:4:\"name\";s:27:\"LearnDash LMS - Course Grid\";}i:3;a:3:{s:4:\"slug\";s:29:\"ultimate-addons-for-gutenberg\";s:4:\"init\";s:63:\"ultimate-addons-for-gutenberg/ultimate-addons-for-gutenberg.php\";s:4:\"name\";s:29:\"Ultimate Addons for Gutenberg\";}i:4;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}i:5;a:3:{s:4:\"slug\";s:13:\"presto-player\";s:4:\"init\";s:31:\"presto-player/presto-player.php\";s:4:\"name\";s:13:\"Presto Player\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1277:\"<!-- wp:paragraph -->\n<p>Want to build a platform and offer courses online? Our Learn Digital Marketing template is an elegant and minimalistic design that’ll help showcase your courses on digital marketing. The template promotes you, the expert, within a significant hero section.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>An ‘enroll today’ CTA button integrated into the menu allows potential students to immediately sign up for your courses. The well-integrated newsletter subscription form lets you build a list and send tips and tricks to your students.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Learn Digital Marketing template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Build an online platform to offer courses in digital marketing, using our engaging and minimalistic website template</li><li>Well integrated with popular LMS plugins, such as LearnDash, to create, manage, and offer courses online</li><li>Offer additional resources, such as ebooks, and case studies on a specifically designed page</li><li>Fully functional contact form that allows prospective students to get in touch with you</li><li>A customizable and flexible template that can be tweaked to suit your needs</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:77:\"An ideal website template to offer courses and resources on digital marketing\";s:5:\"pages\";a:6:{s:8:\"id-49814\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:91:\"https://websitedemos.net/wp-content/uploads/2021/02/learn-digital-marketing-02-homepage.jpg\";s:19:\"thumbnail-image-url\";s:91:\"https://websitedemos.net/wp-content/uploads/2021/02/learn-digital-marketing-02-homepage.jpg\";s:18:\"astra-page-api-url\";s:73:\"https://websitedemos.net/learn-digital-marketing-02/wp-json/wp/v2/pages/4\";s:12:\"dynamic-page\";s:3:\"yes\";s:14:\"astra-page-url\";s:46:\"//websitedemos.net/learn-digital-marketing-02/\";s:15:\"astra-sites-tag\";a:1:{i:814;s:8:\"homepage\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-49810\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:88:\"https://websitedemos.net/wp-content/uploads/2021/02/lear