s-tag\";a:8:{i:623;s:7:\"dentist\";i:601;s:6:\"doctor\";i:604;s:10:\"healthcare\";i:605;s:8:\"hospital\";i:399;s:8:\"one-page\";i:1022;s:12:\"professional\";i:463;s:11:\"single-page\";i:607;s:9:\"treatment\";}s:16:\"astra-sites-type\";s:4:\"free\";s:19:\"astra-site-category\";a:2:{i:27;s:8:\"business\";i:39;s:4:\"free\";}s:29:\"astra-sites-template-category\";a:6:{i:2799;s:7:\"dentist\";i:2867;s:6:\"doctor\";i:2834;s:10:\"healthcare\";i:2780;s:8:\"hospital\";i:2841;s:14:\"medical-clinic\";i:2771;s:8:\"one-page\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:2:{i:2490;s:10:\"healthcare\";i:2927;s:8:\"one-page\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:13:\"astra-widgets\";s:4:\"init\";s:31:\"astra-widgets/astra-widgets.php\";s:4:\"name\";s:13:\"Astra Widgets\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:964:\"<!-- wp:paragraph -->\n<p>The Dentist Clinic website template is a clean, modern design with reassuring colors and fonts and a contact form front and center. The blue and green are classic medical colors and combine well with the white.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The rest of the design provides areas to tell your story, outline products and services and patient testimonials. There are also attractive calls to action throughout, everything you need to build a website for a practice.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Dentist Clinic template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Uses colors we automatically relate to medicine</li><li>Excellent layout with lots of content areas and whitespace</li><li>Includes common content areas a dentist would require</li><li>Attractive calls to action throughout</li><li>Full compatibility with leading page builders</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:72:\"Well-designed template ideal for dentists, clinics and medical practices\";s:5:\"pages\";a:1:{s:8:\"id-52344\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:78:\"https://websitedemos.net/wp-content/uploads/2019/10/dental-clinic-homepage.jpg\";s:19:\"thumbnail-image-url\";s:78:\"https://websitedemos.net/wp-content/uploads/2019/10/dental-clinic-homepage.jpg\";s:18:\"astra-page-api-url\";s:59:\"https://websitedemos.net/dentist-02/wp-json/wp/v2/pages/384\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:30:\"//websitedemos.net/dentist-02/\";s:15:\"astra-sites-tag\";a:2:{i:423;s:4:\"home\";i:463;s:11:\"single-page\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}}}s:19:\"related-bb-template\";s:0:\"\";s:26:\"related-elementor-template\";i:33461;s:26:\"related-gutenberg-template\";i:48442;}s:8:\"id-48442\";a:22:{s:5:\"title\";s:14:\"Dentist Clinic\";s:2:\"id\";i:48442;s:12:\"publish-date\";i:1603913248;s:18:\"featured-image-url\";s:68:\"https://websitedemos.net/wp-content/uploads/2020/10/dentist-08-1.jpg\";s:19:\"thumbnail-image-url\";s:77:\"https://websitedemos.net/wp-content/uploads/2020/10/dentist-08-1-600x2480.jpg\";s:28:\"fullpage-thumbnail-image-url\";s:77:\"https://websitedemos.net/wp-content/uploads/2020/10/dentist-08-1-400x1653.jpg\";s:14:\"astra-site-url\";s:29:\"//websitedemos.net/dentist-08\";s:20:\"astra-site-parent-id\";i:1733;s:15:\"astra-sites-tag\";a:3:{i:338;s:6:\