28;s:7:\"massage\";i:527;s:17:\"massage-therapist\";i:529;s:13:\"physiotherapy\";i:531;s:11:\"reflexology\";i:533;s:10:\"relaxation\";i:650;s:5:\"salon\";i:651;s:8:\"skincare\";i:530;s:3:\"spa\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:27;s:8:\"business\";}s:29:\"astra-sites-template-category\";a:4:{i:2790;s:14:\"beauty-fashion\";i:2821;s:14:\"feminine-girly\";i:2822;s:15:\"massage-therapy\";i:2856;s:3:\"spa\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:1:{i:2479;s:6:\"beauty\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:884:\"<!-- wp:paragraph -->\n<p>The Spa website template has a relaxed vibe ideal for the industry. It uses comfortable colors, reassuring fonts and images and helps create that caring feel the industry is well known for.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The design includes lots of opportunities to add products and services, testimonials, price lists and booking features. It’s the only template you need to create an online presence for your spa or treatment business.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Spa template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Professional layout with calming design</li><li>Balanced colors and fonts</li><li>Lots of content areas for products and services</li><li>Can integrate with booking plugins</li><li>Full compatibility with drag and drop page builders</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:84:\"Calm, inviting web design designed especially for spas, salons and beauty businesses\";s:5:\"pages\";a:4:{s:8:\"id-23888\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:77:\"https://websitedemos.net/wp-content/uploads/2019/07/lotus-spa-04-homepage.jpg\";s:19:\"thumbnail-image-url\";s:77:\"https://websitedemos.net/wp-content/uploads/2019/07/lotus-spa-04-homepage.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/lotus-spa-04/wp-json/wp/v2/pages/2202\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:32:\"//websitedemos.net/lotus-spa-04/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}}s:8:\"id-23885\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2019/07/lotus-spa-04-about-1.jpg\";s:19:\"thumbnail-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2019/07/lotus-spa-04-about-1.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/lotus-spa-04/wp-json/wp/v2/pages/2208\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:38:\"//websitedemos.net/lotus-spa-04/about/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"busines